function PanelTitle({title,sub,action,onClick}:{title:string,sub:string,action?:string,onClick?:()=>void}){return <div className="panel-title"><div><h3>{title}</h3><p>{sub}</p></div>{action&&<button onClick={onClick}>{action}<ChevronRight size={15}/></button>}</div>}
function Urgency({value}:{value:string}){return <span className={`pill urgency ${value.toLowerCase().replace("é","e")}`}><i/>{value}</span>}
function Avatar({name}:{name:string}){const {technicians}=useAppData();const t=technicians.find(x=>x.name===name);return <span className="tiny-avatar" style={{background:t?.color}}>{t?.initials||"?"}</span>}
const technicianStatusKey=(value?:string)=>value==="concluido"||value==="atendimento_finalizado"?"atendido":value||"nao_iniciado";
const technicianStatusLabel=(value?:string)=>({em_atendimento:"Em atendimento pelo técnico",atendido:"Atendido pelo técnico",pendente:"Pendente pelo técnico"} as Record<string,string>)[technicianStatusKey(value)]||"Não iniciado";
const executionDate=(value?:string)=>value?new Date(value).toLocaleString("pt-BR"):"—";
function TechnicianStatusBadge({ticket}:{ticket:Ticket}){const {rows}=useFieldEvents();const job=matchFieldJob(rows,ticket);if(job)return <FieldBadge job={job}/>;const status=technicianStatusKey(ticket.technicianStatus);if(status==="nao_iniciado")return null;return <span className={`technician-status-badge ${status}`}>{technicianStatusLabel(status)}</span>}
function TechnicianExecutionPanel({ticket,onOfficialComplete,onReprogram}:{ticket:Ticket;onOfficialComplete?:()=>void;onReprogram?:()=>void}){const {profile}=useAuth();const status=technicianStatusKey(ticket.technicianStatus);const canReview=profile?.role==="admin"||profile?.role==="analista";if(status==="nao_iniciado"&&!ticket.technicianNotes&&!ticket.serviceStartedAt&&!ticket.routeStartedAt)return null;return <section className="technician-execution span-2"><div className="technician-execution-head"><div><span>EXECUÇÃO DO TÉCNICO</span><h3>{technicianStatusLabel(status)}</h3></div><TechnicianStatusBadge ticket={ticket}/></div><dl><div><dt>Técnico responsável</dt><dd>{ticket.tech||"Não definido"}</dd></div><div><dt>Status do técnico</dt><dd>{technicianStatusLabel(status)}</dd></div><div><dt>Início do atendimento</dt><dd>{executionDate(ticket.serviceStartedAt)}</dd></div><div><dt>Fim do atendimento</dt><dd>{executionDate(ticket.serviceFinishedAt)}</dd></div><div><dt>Atendido pelo técnico em</dt><dd>{executionDate(ticket.completedByTechnicianAt)}</dd></div><div><dt>Motivo da pendência</dt><dd>{ticket.technicianPendingReason||"—"}</dd></div><div className="wide"><dt>Observação do técnico</dt><dd>{ticket.technicianNotes||"—"}</dd></div><div><dt>Rota iniciada em</dt><dd>{executionDate(ticket.routeStartedAt)}</dd></div><div><dt>Rota finalizada em</dt><dd>{executionDate(ticket.routeFinishedAt)}</dd></div><div><dt>KM inicial</dt><dd>{Number.isFinite(ticket.routeStartOdometer)?ticket.routeStartOdometer:"—"}</dd></div><div><dt>KM final</dt><dd>{Number.isFinite(ticket.routeEndOdometer)?ticket.routeEndOdometer:"—"}</dd></div><div><dt>KM percorrido real</dt><dd>{Number.isFinite(ticket.routeActualKm)?`${ticket.routeActualKm} km`:"—"}</dd></div></dl>{canReview&&status==="atendido"&&ticket.status!=="Concluído"&&<button type="button" className="btn official-complete" onClick={onOfficialComplete}><Check size={16}/>Concluir oficialmente</button>}{canReview&&status==="pendente"&&<div className="technician-review-actions"><button type="button" className="btn secondary" onClick={onReprogram}>Reprogramar chamado</button><span>Você também pode alterar o status administrativo acima ou manter o chamado para análise.</span></div>}</section>}

function Kanban({items,setItems,initialSearch,flash}:{items:Ticket[];setItems:(x:Ticket[])=>void;initialSearch:string;flash:(s:string)=>void}){
 const {configured,profile}=useAuth();const suggestedAnalyst=configured&&profile?.role==="analista"?profile.analystName||"":"";
 const {technicians:techs,branches:filiaisBase,analysts,createTicket,updateTicket,cancelTicket,deleteTicket}=useAppData();
 const cols:Status[]=["Novo","Programado","Aguardando compra","Aguardando entrega","Em atendimento","Concluído","Cancelado"];
 const [order,setOrder]=useState("oldest"); const [query,setQuery]=useState(initialSearch); const [tech,setTech]=useState(""); const [urgency,setUrgency]=useState(""); const [status,setStatus]=useState(""); const [city,setCity]=useState(""); const [analyst,setAnalyst]=useState("");const [plannedDate,setPlannedDate]=useState("");const [dueDate,setDueDate]=useState("");const [issue,setIssue]=useState(""); const [editing,setEditing]=useState<Ticket|null>(null); const [isNew,setIsNew]=useState(false); const [formError,setFormError]=useState("");
 useEffect(()=>setQuery(initialSearch),[initialSearch]);
 const shown=items.filter(t=>{const hay=`${t.number} ${t.branch} ${t.branchNumber||""} ${t.city} ${t.desc} ${t.tech||""} ${t.status} ${ticketAnalyst(t)}`.toLowerCase();const coordIssue=issue==="sem_coordenadas"&&!isValidCoordinate(t.latitude,t.longitude);const branchIssue=issue==="revisar_filial"&&t.reviewBranch;const overdue=issue==="atrasado"&&!!t.dueAt&&t.dueAt<new Date().toISOString().slice(0,10)&&!(["Concluído","Fechado","Cancelado"] as Status[]).includes(t.status);return(!query||hay.includes(query.toLowerCase()))&&(!tech||t.tech===tech)&&(!urgency||t.urgency===urgency)&&(!status||canonicalStatus(t.status)===status)&&(!city||t.city===city)&&(!analyst||ticketAnalyst(t)===analyst)&&(!plannedDate||t.date===plannedDate)&&(!dueDate||t.dueAt===dueDate)&&(!issue||coordIssue||branchIssue||overdue)});
 const dateRank=(v:unknown)=>{const t=Date.parse(String(v||""));return Number.isFinite(t)?t:Infinity};
 const sorted=(list:Ticket[])=>[...list].sort((a,b)=>{const av=dateRank(a.openedAt),bv=dateRank(b.openedAt),ad=dateRank(a.dueAt),bd=dateRank(b.dueAt);const oldest=av===bv?0:av<bv?-1:1;const due=ad===bd?0:ad<bd?-1:1;const priority=(t:Ticket)=>({Alta:0,"Média":1,Baixa:2}[t.urgency]??3);return (order==="manual"?0:order==="newest"?(av===bv?0:av===Infinity?1:bv===Infinity?-1:-oldest):order==="due"?due||oldest:order==="urgency"?priority(a)-priority(b)||oldest:oldest)||String(a.number).localeCompare(String(b.number),"pt-BR",{numeric:true});});
 const openNew=()=>{const f=filiaisBase[0];setFormError("");setEditing({id:0,number:"",branch:f?.nome||"Filial não localizada",branchId:f?.id,branchNumber:f?.numeroFilial,branchCnpj:f?.cnpj,city:f?`${f.cidade}, ${f.uf}`:"",uf:f?.uf||"",address:f?.endereco||"",latitude:f?.latitude??null,longitude:f?.longitude??null,desc:"",status:"Novo",urgency:"Média",duration:60,analistaResponsavel:suggestedAnalyst,analyst:suggestedAnalyst,openedAt:new Date().toISOString().slice(0,10),tech:undefined,date:undefined,routeId:undefined,routeOrder:undefined,planningStatus:"nao_planejado",reviewBranch:!f});setIsNew(true)};
 const save=()=>{if(!editing)return;const missing=[];if(!editing.number.trim())missing.push("número do chamado");if(!editing.desc.trim())missing.push("descrição");if(!editing.branchNumber&&!editing.city.trim())missing.push("filial ou cidade");if(missing.length){setFormError(`Preencha: ${missing.join(", ")}.`);return}if(items.some(item=>item.id!==editing.id&&normalizeText(item.number)===normalizeText(editing.number))){setFormError("Já existe um chamado com este número.");return}if(editing.status==="Cancelado"&&!window.confirm("Cancelar este chamado e removê-lo do planejamento?"))return;const clean={...editing,number:editing.number.trim(),desc:editing.desc.trim(),city:editing.city.trim(),address:editing.address.trim()||"Endereço não informado",duration:Number.isFinite(editing.duration)&&editing.duration>0?editing.duration:60,tech:editing.tech||undefined,date:editing.date||undefined};if(isNew){const {id:ignored,...draft}=clean;createTicket({...draft,routeId:undefined,routeOrder:undefined,planningStatus:"nao_planejado"})}else updateTicket(clean);setEditing(null);setIsNew(false);setFormError("");flash(isNew?"Chamado criado com sucesso":"Chamado atualizado com sucesso")};
 const cancelCurrent=()=>{if(!editing||!window.confirm("Cancelar este chamado e removê-lo do planejamento?"))return;cancelTicket(editing.id);setEditing(null);flash("Cancelando chamado...")};
 const deleteCurrent=async()=>{if(!editing||!window.confirm("Tem certeza que deseja excluir este chamado? Essa ação não pode ser desfeita."))return;flash("Excluindo chamado...");const deleted=await deleteTicket(editing.id);if(deleted){setEditing(null);flash("Chamado excluído e sincronizado.")}else flash("Não foi possível excluir o chamado. Confira o aviso exibido acima.")};
 const clearFilters=()=>{setQuery("");setTech("");setUrgency("");setStatus("");setCity("");setAnalyst("");setPlannedDate("");setDueDate("");setIssue("")};const exportVisible=()=>downloadCsv("chamados-filtrados.csv",[["Chamado","Filial","Cidade","Status","Urgência","Técnico","Analista","Data planejada","Data limite"],...shown.map(t=>[t.number,t.branch,t.city,t.status,t.urgency,t.tech,ticketAnalyst(t),t.date,t.dueAt])]);
 return <><PageHead title="Chamados" sub="Acompanhe e organize o fluxo de atendimentos."><button className="btn secondary" onClick={exportVisible}><Download size={17}/>Exportar CSV</button><button className="btn primary" onClick={openNew}><Plus size={17}/>Novo chamado</button></PageHead>
 <div className="toolbar kanban-filters"><div className="searchbox"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar chamados..."/></div><select className="select" value={tech} onChange={e=>setTech(e.target.value)}><option value="">Todos os técnicos</option>{techs.map(t=><option key={t.name}>{t.name}</option>)}</select><select className="select" value={analyst} onChange={e=>setAnalyst(e.target.value)}><option value="">Todos os analistas</option>{analysts.map(x=><option key={x}>{x}</option>)}</select><select className="select" value={urgency} onChange={e=>setUrgency(e.target.value)}><option value="">Urgências</option>{["Alta","Média","Baixa"].map(x=><option key={x}>{x}</option>)}</select><select className="select" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Status</option>{cols.map(x=><option key={x}>{x}</option>)}</select><select className="select" value={city} onChange={e=>setCity(e.target.value)}><option value="">Cidades</option>{cidadesFiliais.map(x=><option key={x} value={`${x}, SC`}>{x}</option>)}</select><input className="select" type="date" title="Data planejada" value={plannedDate} onChange={e=>setPlannedDate(e.target.value)}/><input className="select" type="date" title="Data limite" value={dueDate} onChange={e=>setDueDate(e.target.value)}/><select className="select" value={issue} onChange={e=>setIssue(e.target.value)}><option value="">Todas as situações</option><option value="sem_coordenadas">Sem coordenadas</option><option value="revisar_filial">Revisar filial</option><option value="atrasado">Prazo vencido</option></select><select className="select" aria-label="Ordenar dentro das colunas" value={order} onChange={e=>setOrder(e.target.value)}><option value="oldest">Mais antigos primeiro</option><option value="newest">Mais recentes primeiro</option><option value="due">Prazo mais próximo</option><option value="urgency">Maior urgência</option><option value="manual">Número do chamado</option></select><button className="btn secondary" onClick={clearFilters}>Limpar</button><span className="result-count">{shown.length} chamados</span></div>
 <div className="kanban">{cols.map((s,i)=><div className="kanban-col" key={s}><div className="kanban-head"><span className={`status-dot s${i}`}/><b>{s}</b><em>{shown.filter(t=>canonicalStatus(t.status)===s).length}</em><MoreHorizontal size={17}/></div>{sorted(shown.filter(t=>canonicalStatus(t.status)===s)).map(t=><div key={t.id} onClick={()=>{setFormError("");setEditing({...t,status:canonicalStatus(t.status)});setIsNew(false)}}><TicketCard t={t}/></div>)}
 {i<2&&<button className="add-card" onClick={openNew}><Plus size={15}/>Adicionar chamado</button>}</div>)}</div>{editing&&<TicketModal ticket={editing} error={formError} onChange={value=>{setFormError("");setEditing(value)}} onCancel={()=>{setEditing(null);setFormError("")}} onSave={save} onCancelTicket={!isNew?cancelCurrent:undefined} onDelete={!isNew?deleteCurrent:undefined} onOfficialComplete={!isNew?()=>{updateTicket({...editing,status:"Concluído"});setEditing(null);flash("Chamado concluído oficialmente")}:undefined}/>}</>;
}
function TicketCard({t}:{t:Ticket}){return <div className="ticket-card"><div><b>{t.number}</b><Urgency value={t.urgency}/></div><span className="field-official">Status da carteira: {t.sourceStatus||t.status}</span><TechnicianStatusBadge ticket={t}/><h4>{ticketSubject(t)}</h4><p><Building2 size={14}/>{safeBranchLabel(t)}</p><p><MapPin size={14}/>{t.city}</p><p className="ticket-analyst"><UserRound size={14}/>{ticketAnalyst(t)}</p>{t.tech&&<div className="ticket-foot"><span><Avatar name={t.tech}/>{t.tech}</span><span><CalendarDays size={14}/>{t.date||"A definir"}</span></div>}</div>}
function TicketModal({ticket,error="",onChange,onCancel,onSave,onCancelTicket,onDelete,onOfficialComplete}:{ticket:Ticket;error?:string;onChange:(t:Ticket)=>void;onCancel:()=>void;onSave:()=>void;onCancelTicket?:()=>void;onDelete?:()=>void;onOfficialComplete?:()=>void}){
 const {technicians:techs,branches:filiaisBase,analysts}=useAppData();
 const set=(k:keyof Ticket,v:any)=>onChange({...ticket,[k]:v}); const selectBranch=(id:string)=>{const f=filiaisBase.find(x=>String(x.id)===id);if(f)onChange({...ticket,branch:f.nome,branchId:f.id,branchNumber:f.numeroFilial,branchCnpj:f.cnpj,city:`${f.cidade}, ${f.uf}`,uf:f.uf,address:f.endereco,latitude:f.latitude,longitude:f.longitude,reviewBranch:false});else onChange({...ticket,branch:"Filial não localizada",branchId:undefined,branchNumber:undefined,branchCnpj:undefined,city:"",uf:"",address:"",latitude:null,longitude:null,reviewBranch:true})};
 return <div className="modal-bg tech-modal-bg"><div className="tech-modal ticket-modal"><div className="tech-modal-head"><div><span className="eyebrow">CHAMADO</span><h2>{ticket.id?`Editar ${ticket.number}`:"Novo chamado"}</h2><p>Dados do atendimento e planejamento operacional.</p></div><button onClick={onCancel}><X/></button></div><OnlineTechnicalReport ticket={ticket}/><div className="tech-form">
 <label className="field"><span>Número *</span><input value={ticket.number} readOnly={!!ticket.id} title={ticket.id?"Número permanente do chamado":"Informe um número único"} onChange={e=>set("number",e.target.value)}/></label><label className="field"><span>Status</span><select value={ticket.status} onChange={e=>set("status",e.target.value)}>{["Novo","Programado","Aguardando compra","Aguardando entrega","Em atendimento","Concluído","Cancelado"].map(x=><option key={x}>{x}</option>)}</select></label>
 <label className="field span-2"><span>Filial</span><select value={filiaisBase.find(f=>f.numeroFilial===ticket.branchNumber)?.id||""} onChange={e=>selectBranch(e.target.value)}><option value="">Filial não localizada / informar cidade</option>{filiaisBase.map(f=><option key={f.id} value={f.id}>{f.numeroFilial} — {f.nome} — {f.cidade}</option>)}</select></label><label className="field"><span>Cidade *</span><input value={ticket.city} onChange={e=>set("city",e.target.value)}/></label><label className="field"><span>UF</span><input value={ticket.uf||""} maxLength={2} onChange={e=>set("uf",e.target.value.toUpperCase())}/></label><label className="field span-2"><span>Endereço</span><input value={ticket.address} onChange={e=>set("address",e.target.value)}/></label>
 {ticket.sourceFields?.subject ? <>
 <label className="field span-2"><span>Assunto (Movidesk)</span><input value={ticketSubject(ticket)} readOnly/></label>
 <label className="field span-2"><span>Descrição do Ticket (Movidesk)</span><textarea value={ticketDescription(ticket)} rows={5} readOnly/></label>
 </> : <label className="field span-2"><span>Descrição / assunto *</span><textarea value={ticket.desc} onChange={e=>set("desc",e.target.value)}/></label>}<label className="field"><span>Urgência</span><select value={ticket.urgency} onChange={e=>set("urgency",e.target.value)}>{["Alta","Média","Baixa"].map(x=><option key={x}>{x}</option>)}</select></label><label className="field"><span>Analista responsável</span><select value={normalizeText(ticket.analistaResponsavel||ticket.analyst)==="naodefinido"?"":ticket.analistaResponsavel||ticket.analyst||""} onChange={e=>onChange({...ticket,analistaResponsavel:e.target.value||undefined,analyst:e.target.value||undefined,dataAtribuicaoAnalista:e.target.value?new Date().toISOString():undefined})}><option value="">Não definido</option>{analysts.filter(x=>normalizeText(x)!=="naodefinido").map(x=><option key={x}>{x}</option>)}</select></label>
 <label className="field"><span>Técnico planejado</span><select value={ticket.tech||""} onChange={e=>set("tech",e.target.value)}><option value="">A definir</option>{techs.map(t=><option key={t.name}>{t.name}</option>)}</select></label><label className="field"><span>Data planejada</span><input type="date" value={ticket.date||""} onChange={e=>set("date",e.target.value)}/></label><label className="field"><span>Tempo estimado (min)</span><input type="number" value={ticket.duration} onChange={e=>set("duration",Number(e.target.value))}/></label><label className="field"><span>Data de abertura</span><input type="date" value={ticket.openedAt||""} onChange={e=>set("openedAt",e.target.value)}/></label><label className="field"><span>Data limite</span><input type="date" value={ticket.dueAt||""} onChange={e=>set("dueAt",e.target.value)}/></label><label className="field span-2"><span>Observações</span><textarea value={ticket.notes||""} onChange={e=>set("notes",e.target.value)}/></label><TechnicianExecutionPanel ticket={ticket} onOfficialComplete={onOfficialComplete} onReprogram={()=>onChange({...ticket,date:undefined,routeId:undefined,routeOrder:undefined,planningStatus:"nao_planejado"})}/>
 {error&&<div className="form-error span-2" role="alert">{error}</div>}</div><div className="tech-modal-actions split-actions"><div>{onCancelTicket&&ticket.status!=="Cancelado"&&<button className="btn danger-soft" onClick={onCancelTicket}><Ban size={16}/>Cancelar chamado</button>}{onDelete&&<button className="btn danger-text" onClick={onDelete}><Trash2 size={16}/>Excluir</button>}</div><div><button className="btn secondary" onClick={onCancel}>Voltar</button><button className="btn primary" onClick={onSave}><Check size={17}/>Salvar chamado</button></div></div></div></div>;
}

function Planner({items,setItems,go,flash,openRoute}:{openRoute:(tech:string,date:string)=>void;items:Ticket[];setItems:(x:Ticket[])=>void;go:(p:Page)=>void;flash:(s:string)=>void}){
 const {rows:fieldRows}=useFieldEvents();
 const {technicians:techs,branches,analysts,updateTicket,removeTicketFromRoute,cancelTicket,deleteTicket}=useAppData();
 const [offset,setOffset]=useState(0); const [planning,setPlanning]=useState<Ticket|null>(null);const [slot,setSlot]=useState<{tech:string;date:string}|null>(null);const [techFilter,setTechFilter]=useState("");const [analystFilter,setAnalystFilter]=useState("");const [cityFilter,setCityFilter]=useState("");const [urgencyFilter,setUrgencyFilter]=useState("");const [statusFilter,setStatusFilter]=useState("");
 const monday=useMemo(()=>{const d=new Date();const day=d.getDay();d.setDate(d.getDate()-(day===0?6:day-1)+offset*7);d.setHours(12,0,0,0);return d},[offset]);
 const days=Array.from({length:6},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return d});
 const iso=(d:Date)=>d.toISOString().slice(0,10); const labels=["SEG","TER","QUA","QUI","SEX","SÁB"];
 const [today,setToday]=useState(()=>new Date().toLocaleDateString("sv-SE",{timeZone:"America/Sao_Paulo"}));
 useEffect(()=>{const update=()=>setToday(new Date().toLocaleDateString("sv-SE",{timeZone:"America/Sao_Paulo"}));const timer=window.setInterval(update,30000);window.addEventListener("focus",update);return()=>{window.clearInterval(timer);window.removeEventListener("focus",update)}},[]);
 const savePlan=()=>{if(!planning)return;const original=items.find(t=>t.id===planning.id);if(original&&matchFieldJob(fieldRows,original)&&(original.tech!==planning.tech||original.date!==planning.date)){flash("Chamado já enviado. Mantenha o técnico e a data desta jornada.");return;}updateTicket({...planning,routeId:planning.tech&&planning.date?`${planning.tech}-${planning.date}`:undefined,planningStatus:planning.planningStatus||"em_rota_rascunho",status:planning.status==="Novo"&&planning.planningStatus==="rota_confirmada"?"Programado":planning.status});setPlanning(null);flash("Planejamento e chamado atualizados")};
 const removePlan=()=>{if(!planning)return;if(matchFieldJob(fieldRows,items.find(t=>t.id===planning.id)||planning)){flash("Atendimento já enviado. Remoção indisponível nesta versão.");return;}if(canonicalStatus(planning.status)==="Concluído"&&planning.date&&planning.date<=today&&!window.confirm("Este chamado está concluído. Remover o registro da agenda apagará sua programação histórica. Continuar?"))return;removeTicketFromRoute(planning.id);setPlanning(null);flash("Removendo chamado da rota...")};
 const cancelPlan=()=>{if(planning&&matchFieldJob(fieldRows,items.find(t=>t.id===planning.id)||planning)){flash("Atendimento já enviado. Cancelamento indisponível nesta versão.");return;}if(!planning||!window.confirm("Cancelar este chamado e removê-lo do planejamento?"))return;cancelTicket(planning.id);setPlanning(null);flash("Cancelando chamado...")};const deletePlan=()=>{if(planning&&matchFieldJob(fieldRows,items.find(t=>t.id===planning.id)||planning)){flash("Atendimento já enviado. Exclusão indisponível nesta versão.");return;}if(!planning||!window.confirm("Tem certeza que deseja excluir este chamado? Essa ação não pode ser desfeita."))return;deleteTicket(planning.id);setPlanning(null);flash("Excluindo chamado...")};
 const activeTechs=techs.filter(t=>t.active);const plannerItems=items.filter(t=>(!techFilter||t.tech===techFilter)&&(!analystFilter||ticketAnalyst(t)===analystFilter)&&(!cityFilter||t.city.startsWith(cityFilter))&&(!urgencyFilter||t.urgency===urgencyFilter)&&(!statusFilter||canonicalStatus(t.status)===statusFilter));const visibleTechs=activeTechs.filter(t=>!techFilter||t.name===techFilter);const exportWeek=()=>downloadCsv("planner-semanal.csv",[["Chamado","Filial","Cidade","Técnico","Analista","Data"],...plannerItems.filter(t=>days.some(d=>t.date===iso(d))).map(t=>[t.number,t.branch,t.city,t.tech,ticketAnalyst(t),t.date])]);
 return <><PageHead title="Planner semanal" sub="Visualize a agenda da equipe e distribua os chamados."><button className="btn secondary" onClick={exportWeek}><Download size={17}/>Exportar CSV</button><button className="btn primary" disabled={!activeTechs.length} onClick={()=>setSlot({tech:activeTechs[0]?.name||"",date:iso(days[0])})}><Plus size={17}/>Planejar chamado</button></PageHead>
 <div className="toolbar planner-filters"><select className="select" value={techFilter} onChange={e=>setTechFilter(e.target.value)}><option value="">Todos os técnicos</option>{techs.map(t=><option key={t.name}>{t.name}</option>)}</select><select className="select" value={analystFilter} onChange={e=>setAnalystFilter(e.target.value)}><option value="">Todos os analistas</option>{analysts.map(x=><option key={x}>{x}</option>)}</select><select className="select" value={cityFilter} onChange={e=>setCityFilter(e.target.value)}><option value="">Todas as cidades</option>{cidadesFiliais.map(x=><option key={x}>{x}</option>)}</select><select className="select" value={urgencyFilter} onChange={e=>setUrgencyFilter(e.target.value)}><option value="">Todas as urgências</option>{["Alta","Média","Baixa"].map(x=><option key={x}>{x}</option>)}</select><select className="select" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="">Todos os status</option>{["Novo","Programado","Aguardando compra","Aguardando entrega","Em atendimento","Concluído","Cancelado"].map(x=><option key={x}>{x}</option>)}</select><button className="btn secondary" onClick={()=>{setTechFilter("");setAnalystFilter("");setCityFilter("");setUrgencyFilter("");setStatusFilter("")}}>Limpar</button><span className="result-count">{plannerItems.filter(t=>days.some(d=>t.date===iso(d))).length} chamados na semana</span></div>
 <div className="week-nav"><button onClick={()=>setOffset(offset-1)}>‹</button><b>{days[0].toLocaleDateString("pt-BR",{day:"2-digit",month:"short"})} — {days[5].toLocaleDateString("pt-BR",{day:"2-digit",month:"short",year:"numeric"})}</b><button onClick={()=>setOffset(offset+1)}>›</button><button className="today" onClick={()=>setOffset(0)}>Hoje</button></div>
 <div style={{display:"flex",gap:18,flexWrap:"wrap",margin:"12px 0",fontSize:12}}><span>✅ Concluído (mantido na agenda)</span><span>⚠️ Dia anterior sem conclusão — revisar ou reagendar</span><span>Programado — atendimento pendente</span></div><div className="planner panel"><div className="planner-row planner-head"><div>TÉCNICO</div>{days.map((d,i)=><div className={iso(d)===today?"today-col":""} key={iso(d)}><b>{labels[i]}</b><span>{d.getDate()}</span></div>)}</div>
 {visibleTechs.map(tech=><div className="planner-row" key={tech.name}><div className="tech-cell"><Avatar name={tech.name}/><span><b>{tech.name}</b><small>{plannerItems.filter(x=>x.tech===tech.name&&days.some(d=>x.date===iso(d))).length} chamados</small></span></div>{days.map((d,di)=><div className={iso(d)===today?"today-col day-cell":"day-cell"} key={iso(d)}>{plannerItems.filter(x=>x.tech===tech.name&&x.date===iso(d)).sort((a,b)=>(matchFieldJob(fieldRows,a)?.position??a.routeOrder??9999)-(matchFieldJob(fieldRows,b)?.position??b.routeOrder??9999)).map(t=>{const branch=resolveTicketBranch(t,branches);const branchLabel=branch?(safeBranchNumber(branch.numeroFilial)?`FL ${Number(branch.numeroFilial)}`:branch.nome):safeBranchLabel(t);const state=plannerState(t.status,t.date,today);const job=matchFieldJob(fieldRows,t);return <button className={`plan-card plan-${state} ${job?`field-plan-${job.state}`:""}`} style={{borderLeftColor:state==="overdue"?"#d97706":state==="complete"?"#16a34a":tech.color}} key={t.id} onClick={()=>setPlanning({...t})}><b style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>{job?`${job.position}. `:""}{t.number}{state==="complete"?<span title="Concluído" aria-label="Concluído" style={{color:"#15803d",fontSize:15}}>✅</span>:state==="overdue"?<span title="Atendimento vencido: revisar ou reagendar" aria-label="Atrasado" style={{color:"#a16207",fontSize:15}}>⚠️</span>:null}</b><span>{branchLabel}</span><span>{branch?.cidade||t.city.split(",")[0]||"Cidade não definida"}</span>{state==="overdue"?<span style={{color:"#92400e",fontWeight:700}}>Revisar / reagendar</span>:state==="complete"?<span style={{color:"#15803d"}}>Concluído{t.date&&t.date>today?" · revisar rota futura":""}</span>:null}<TechnicianStatusBadge ticket={t}/></button>})}{plannerItems.some(x=>x.tech===tech.name&&x.date===iso(d))&&<button type="button" className="btn secondary" style={{fontSize:10,padding:4,marginTop:4}} onClick={()=>openRoute(tech.name,iso(d))}>Abrir rota</button>}<button className="slot-plus" aria-label={`Adicionar chamado para ${tech.name} em ${iso(d)}`} onClick={()=>setSlot({tech:tech.name,date:iso(d)})}><Plus size={15}/></button></div>)}</div>)}</div>{planning&&<PlanModal ticket={planning} onChange={setPlanning} onCancel={()=>setPlanning(null)} onSave={savePlan} onRemove={removePlan} onCancelTicket={cancelPlan} onDelete={deletePlan} onOfficialComplete={()=>{updateTicket({...planning,status:"Concluído"});setPlanning(null);flash("Chamado concluído oficialmente")}}/>} {slot&&<PlannerAddModal slot={slot} onClose={()=>setSlot(null)} flash={flash}/>}</>;
}
function PlanModal({ticket,onChange,onCancel,onSave,onRemove,onCancelTicket,onDelete,onOfficialComplete}:{ticket:Ticket;onChange:(t:Ticket)=>void;onCancel:()=>void;onSave:()=>void;onRemove:()=>void;onCancelTicket:()=>void;onDelete:()=>void;onOfficialComplete:()=>void}){const {technicians:techs}=useAppData();return <div className="modal-bg tech-modal-bg"><div className="tech-modal planner-modal"><div className="tech-modal-head"><div><span className="eyebrow">PLANEJAMENTO</span><h2>Editar chamado no Planner</h2><p>{ticket.number} · {ticket.branch}</p></div><button onClick={onCancel}><X/></button></div><div className="tech-form"><label className="field span-2"><span>Descrição</span><textarea value={ticket.desc} onChange={e=>onChange({...ticket,desc:e.target.value})}/></label><label className="field"><span>Status</span><select value={ticket.status} onChange={e=>onChange({...ticket,status:e.target.value as Status})}>{["Novo","Programado","Aguardando compra","Aguardando entrega","Em atendimento","Concluído","Cancelado"].map(status=><option key={status}>{status}</option>)}</select></label><label className="field"><span>Urgência</span><select value={ticket.urgency} onChange={e=>onChange({...ticket,urgency:e.target.value as Ticket["urgency"]})}>{["Alta","Média","Baixa"].map(value=><option key={value}>{value}</option>)}</select></label><label className="field"><span>Técnico</span><select value={ticket.tech||""} onChange={e=>onChange({...ticket,tech:e.target.value})}>{techs.map(t=><option key={t.name}>{t.name}</option>)}</select></label><label className="field"><span>Data planejada</span><input type="date" value={ticket.date||""} onChange={e=>onChange({...ticket,date:e.target.value})}/></label><label className="field"><span>Ordem na rota</span><input type="number" min={1} value={ticket.routeOrder||1} onChange={e=>onChange({...ticket,routeOrder:Number(e.target.value)})}/></label><label className="field"><span>Tempo estimado</span><input type="number" min={1} value={ticket.duration} onChange={e=>onChange({...ticket,duration:Number(e.target.value)})}/></label><label className="field span-2"><span>Status do planejamento</span><select value={ticket.planningStatus||"nao_planejado"} onChange={e=>onChange({...ticket,planningStatus:e.target.value as Ticket["planningStatus"]})}><option value="nao_planejado">Não planejado</option><option value="em_rota_rascunho">Em rota rascunho</option><option value="rota_confirmada">Rota confirmada</option></select></label><label className="field span-2"><span>Observações</span><textarea value={ticket.notes||""} onChange={e=>onChange({...ticket,notes:e.target.value})}/></label><TechnicianExecutionPanel ticket={ticket} onOfficialComplete={onOfficialComplete} onReprogram={()=>onChange({...ticket,date:undefined,routeId:undefined,routeOrder:undefined,planningStatus:"nao_planejado"})}/></div><div className="tech-modal-actions split-actions"><div><button className="btn danger-soft" onClick={onCancelTicket}><Ban size={16}/>Cancelar chamado</button><button className="btn danger-text" onClick={onDelete}><Trash2 size={16}/>Excluir</button></div><div><button className="btn secondary" onClick={onRemove}>Remover da rota</button><button className="btn secondary" onClick={onCancel}>Voltar</button><button className="btn primary" onClick={onSave}>Salvar alterações</button></div></div></div></div>}

function PlannerAddModal({slot,onClose,flash}:{slot:{tech:string;date:string};onClose:()=>void;flash:(message:string)=>void}){const {tickets,branches,createTicket,assignTicketToPlanner}=useAppData();const available=tickets.filter(ticket=>(!ticket.planningStatus||ticket.planningStatus==="nao_planejado")&&!(["Concluído","Fechado","Cancelado"] as Status[]).includes(ticket.status));const [mode,setMode]=useState<"existing"|"new">("existing");const [ticketId,setTicketId]=useState(available[0]?.id||0);const [planningStatus,setPlanningStatus]=useState<"em_rota_rascunho"|"rota_confirmada">("em_rota_rascunho");const [duration,setDuration]=useState(available[0]?.duration||60);const [order,setOrder]=useState(1);const [notes,setNotes]=useState("");const [number,setNumber]=useState("");const [desc,setDesc]=useState("");const [branchId,setBranchId]=useState(branches[0]?.id||0);const [error,setError]=useState("");const save=()=>{if(mode==="existing"){if(!ticketId){setError("Selecione um chamado disponível.");return}assignTicketToPlanner({ticketId,technician:slot.tech,date:slot.date,planningStatus,duration,routeOrder:order,notes});flash("Chamado adicionado ao planejamento");onClose();return}const branch=branches.find(item=>item.id===branchId);if(!number.trim()||!desc.trim()||!branch){setError("Informe número, descrição e filial.");return}createTicket({number:number.trim(),branch:branch.nome,branchId:branch.id,branchNumber:branch.numeroFilial,city:`${branch.cidade}, ${branch.uf}`,uf:branch.uf,address:branch.endereco,latitude:branch.latitude,longitude:branch.longitude,desc:desc.trim(),status:planningStatus==="rota_confirmada"?"Programado":"Novo",urgency:"Média",tech:slot.tech,date:slot.date,duration:duration||60,openedAt:new Date().toISOString().slice(0,10),notes,routeId:`${slot.tech}-${slot.date}`,routeOrder:order,planningStatus});flash("Novo chamado criado e adicionado ao Planner");onClose()};return <div className="modal-bg tech-modal-bg"><div className="tech-modal planner-add-modal"><div className="tech-modal-head"><div><span className="eyebrow">PLANNER SEMANAL</span><h2>Adicionar chamado ao planejamento</h2><p>{slot.tech} · {new Date(`${slot.date}T12:00`).toLocaleDateString("pt-BR")}</p></div><button onClick={onClose}><X/></button></div><div className="tech-form"><label className="field span-2"><span>Origem do chamado</span><select value={mode} onChange={e=>setMode(e.target.value as "existing"|"new")}><option value="existing">Selecionar chamado existente</option><option value="new">Criar novo chamado</option></select></label>{mode==="existing"?<label className="field span-2"><span>Chamado disponível</span><select value={ticketId} onChange={e=>{const id=Number(e.target.value);setTicketId(id);setDuration(tickets.find(item=>item.id===id)?.duration||60)}}>{available.map(ticket=><option key={ticket.id} value={ticket.id}>{ticket.number} — {ticket.branch} — {ticketSubject(ticket)}</option>)}</select></label>:<><label className="field"><span>Número *</span><input value={number} onChange={e=>setNumber(e.target.value)}/></label><label className="field"><span>Filial *</span><select value={branchId} onChange={e=>setBranchId(Number(e.target.value))}>{branches.map(branch=><option key={branch.id} value={branch.id}>{branch.numeroFilial} — {branch.nome} — {branch.cidade}</option>)}</select></label><label className="field span-2"><span>Descrição *</span><textarea value={desc} onChange={e=>setDesc(e.target.value)}/></label></>}<label className="field"><span>Entrada no planejamento</span><select value={planningStatus} onChange={e=>setPlanningStatus(e.target.value as typeof planningStatus)}><option value="em_rota_rascunho">Rascunho</option><option value="rota_confirmada">Programado / confirmado</option></select></label><label className="field"><span>Tempo estimado (min)</span><input type="number" min={1} value={duration} onChange={e=>setDuration(Number(e.target.value))}/></label><label className="field"><span>Ordem na rota</span><input type="number" min={1} value={order} onChange={e=>setOrder(Number(e.target.value))}/></label><label className="field span-2"><span>Observações</span><textarea value={notes} onChange={e=>setNotes(e.target.value)}/></label>{error&&<div className="form-error span-2">{error}</div>}</div><div className="tech-modal-actions"><button className="btn secondary" onClick={onClose}>Cancelar</button><button className="btn primary" onClick={save}><Plus size={16}/>Adicionar ao Planner</button></div></div></div>}

