 const [suggest,setSuggest]=useState(false);const [dragStop,setDragStop]=useState<number|null>(null);const [routeRefresh,setRouteRefresh]=useState(0);const lastRouteRefresh=useRef(0);const previousRoad=useRef<{group:string;order:{latitude?:number|null;longitude?:number|null;ticket:Ticket|null}[]}|null>(null);const [roadComparison,setRoadComparison]=useState<{signature:string;order:Ticket[];original:RouteCalculation;best:RouteCalculation}|null>(null);const [editing,setEditing]=useState<Ticket|null>(null);const [editingStart,setEditingStart]=useState<RouteStartPoint|null>(null);const [roadRoute,setRoadRoute]=useState<RouteCalculation|null>(null);const [routingBusy,setRoutingBusy]=useState(false);const [routingWarning,setRoutingWarning]=useState("");const [routingSaved,setRoutingSaved]=useState<boolean|null>(null);
