 const activeTechs=techs.filter(item=>item.active);const markManual=()=>{if(optimized)setManualInvalidated(true);setOptimized(false)};const saveRouteChange=async(next:Ticket[],message:string)=>{if(fieldError||!fieldChecked){flash("Aguarde a consulta dos atendimentos online.");return false}if(journey?.finished_at){flash("Jornada encerrada.");return false}if(route.some((t,i)=>locked(t)&&next[i]?.id!==t.id)){flash("Atendimentos iniciados ou encerrados não podem mudar de posição.");return false}if(route.some(t=>matchFieldJob(fieldRows,t)&&!next.some(n=>n.id===t.id))){flash("Não é possível retirar um atendimento já enviado nesta versão.");return false}const fallback=calculateFallbackRoute(getValidRoutePoints([startPoint,...next.map(ticketPoint)]));setRoutingWarning("");const saved=await updateRoute({technician:tech,date:day,ticketIds:next.map(ticket=>ticket.id),planningStatus:"em_rota_rascunho",roadRoute:fallback});if(!saved){setRoutingWarning("Não foi possível adicionar ou atualizar o chamado na rota. Nenhuma alteração visual foi aplicada.");flash("Não foi possível adicionar chamado à rota.");return false}setRoute(next);setRoadRoute(fallback);setRoutingSaved(true);setRoutingWarning("Ordem atualizada. Calculando trajeto por ruas…");markManual();flash(message);return true}; const move=(i:number,d:number)=>{const n=[...route]; const j=i+d;if(j<0||j>=n.length)return;[n[i],n[j]]=[n[j],n[i]];void saveRouteChange(n,"Ordem atualizada no rascunho")};
