 const suggestedDistance=comparison?.best.distanceKm??null;
 useEffect(()=>{let cancelled=false;setRoadComparison(null);setRoadRoute(null);setRoutingSaved(null);if(!route.length||validPoints.length<2||missingCoordinates.length||!isValidCoordinate(startPoint.latitude,startPoint.longitude)){setRoutingBusy(false);setRoutingWarning(route.length?"Coordenadas insuficientes para comparar a rota completa.":"");return;}setRoutingBusy(true);setRoutingWarning("Calculando trajeto por ruas…");const timer=setTimeout(async()=>{try{const points=[{...startPoint,ticket:null as Ticket|null},...routePoints.map(t=>({...t,ticket:t as Ticket|null}))];const group=JSON.stringify([tech,day,routeKey([startPoint]),routePoints.map(t=>[t.id,t.latitude,t.longitude]).sort((a,b)=>Number(a[0])-Number(b[0]))]);const previous=previousRoad.current;const refresh=lastRouteRefresh.current!==routeRefresh;lastRouteRefresh.current=routeRefresh;const result=await compareRoadOrders<{latitude?:number|null;longitude?:number|null;ticket:Ticket|null}>(points,false,previous?.group===group?previous.order:undefined,refresh);if(cancelled)return;previousRoad.current={group,order:result.order};setRoadRoute(result.original);setRoadComparison({signature:routeSignature,original:result.original,best:result.best,order:result.order.flatMap(p=>p.ticket?[p.ticket]:[])});setRoutingWarning(result.original.warning||result.original.error||"");}catch{if(!cancelled)setRoutingWarning("Não foi possível calcular a rota por ruas.");}finally{if(!cancelled)setRoutingBusy(false)}},450);return()=>{cancelled=true;clearTimeout(timer)}},[routeSignature,routeRefresh]);
 const routeFiliais=routePoints;
