 const cancelFromRoute=(ticket:Ticket)=>{if(matchFieldJob(fieldRows,ticket)){flash("Chamado já enviado; alteração bloqueada.");return;}if(!window.confirm("Cancelar este chamado e removê-lo da rota?"))return;cancelTicket(ticket.id);flash("Cancelando chamado...")};const deleteFromRoute=(ticket:Ticket)=>{if(matchFieldJob(fieldRows,ticket)){flash("Chamado já enviado; alteração bloqueada.");return;}if(!window.confirm("Tem certeza que deseja excluir este chamado? Essa ação não pode ser desfeita."))return;deleteTicket(ticket.id);flash("Excluindo chamado...")};
