 {journey&&<div className="routing-warning" role="status">Jornada enviada: {journey.field_jobs.length} chamado(s). Confirme a rota, aguarde o salvamento automático e envie a sequência ao técnico. {journey.finished_at?"Jornada encerrada.":"Atendimentos iniciados permanecem protegidos."}</div>}
 {route.length>0&&route.every(t=>items.some(x=>x.id===t.id&&x.planningStatus==="rota_confirmada"))&&<RouteDispatch tech={tech} date={day} origin={[startPoint.description,startPoint.address].filter(Boolean).join(" · ")} jobs={route.map(t=>({number:t.number,branch:t.branch,address:[t.address,t.city].filter(Boolean).join(" · "),description:t.desc}))}/>}<div className="route-config panel"><label>Técnico <select className="select" value={tech} onChange={e=>setTech(e.target.value)}>{activeTechs.map(t=><option key={t.name}>{t.name}</option>)}</select></label><label>Dia da rota <input className="select" type="date" value={day} onChange={e=>setDay(e.target.value)}/></label><div className="tech-hours"><Clock3 size={17}/><span>Jornada padrão<b>{currentTech.startTime} — {currentTech.endTime}</b></span></div></div>
